"""Writes docs-authority/PARAMETRIC_MODEL.md (AQS-PAR-001): framework, drivers, references,
solver closure and misfits, and the verification list (drivers + register entries flagged
needs_verification), which feeds the testing and prototyping rollout plan."""
import json, os
from .refs import REFS
from . import drivers as DR, solver
ROOT = solver.ROOT
def main():
    d = DR.load(); errs, mis, s, _ = solver.check()
    man = json.load(open(os.path.join(ROOT,'docs-authority/assumptions_manual.json')))
    used = sorted({v['ref'] for v in d.values() if v.get('ref')} | {'CODATA2018','CIAAW2021','GREENWOOD','EDBM_WHEY_2021','SCHLESINGER2011','INCROPERA7','PERRY9'})
    L = ["# Parametric model","","Document number: AQS-PAR-001","Revision: A","Date: 2026-10-15",
         "Authority: AQS-PLAN-007 X-PAR. Generated by `python3 -m flow_graph.param.report`. Study.","",
         "## 1. Framework","",
         "1. Drivers (`flow_graph/param/drivers.json`, loader `drivers.py`): independent inputs. Each has units and a published reference key, a register id, or an owner basis. A value no published source fixes carries `needs_verification` and `verification_test`; the loader fails otherwise.",
         "2. Balance solver (`solver.py`): per-unit transfer functions (stoichiometry, splits, Faraday, energy) compute edge rates and duties from the drivers. `check()` fails on a closure error of a solved unit and lists misfits against the graph.",
         "3. Sizing library (`sizing/`): electrochem (Faraday current, cathode count, DC power), heat (sensible duty, LMTD, area), lines (velocity bore, DN pick), power (PV kWp, 3-phase amps, NEC breaker). Each function names its equation and reference.",
         "4. Generated outputs: scripts in `docs-authority/` call the library with drivers; the commit regenerates them. X-PAR-04 will write graph values from the solver and turn the misfit list into a failing gate.","",
         "## 2. Converted so far","",
         "| Script | Library | Drivers now parametric |","| --- | --- | --- |",
         "| `_ew_sizing.py` (AQS-DUTY-051) | electrochem | F (CODATA 2018, was 96485.0), M_Cu (CIAAW), current density, current efficiency, cell voltage |",
         "| `_hot_draw_coolers.py` | heat | cp HCl/NaOH, design dry bulb, free-convection U |",
         "| `_line_list.py` (AQS-PIP-004) | lines | liquid/gas velocity, slurry and minimum DN; heat loops now sized from kW at ΔT 10 K (was a DN25 default) |",
         "| solver: LEACH acid (case A), BMED, EW currents | electrochem, constants | feed rate, class A oxides, leach extent, HCl stoichiometry, BMED SEC |","",
         "## 3. Solver closure","", ("All solved units close." if not errs else "FAILS: "+"; ".join(errs)),"",
         "## 4. Misfits against the graph","","| Item | Graph | Solved | Deviation | Reference |","| --- | --- | --- | --- | --- |"]
    L += [f"| {a} | {b:.3f} | {c:.3f} | {dv*100:+.1f} % | {r} |" for a,b,c,dv,r in mis]
    L += ["","Findings: (1) BMED_ACID is booked at 16.13 kW on an unsourced 2.1 kWh/kg pair; the published SEC at 2 M is 6.7 kWh/kg base, giving 26.9 kW. (2) Conventional EDBM reaches about 3.6 M acid; the graph carries 20 wt% (about 6 M) acid and base. (3) The EW cell voltage is 2.5 V in AQS-DUTY-051 and 2.8 V in AQS-ELEC-004; both await a bench cell. These are resolved in X-PAR-04 when the solver writes the graph.","",
          "## 5. Drivers","","| Driver | Value | Units | Source | Verify |","| --- | --- | --- | --- | --- |"]
    for k,v in d.items():
        L.append(f"| {k} | {json.dumps(v['value'])} | {v['units']} | {v.get('ref') or v.get('register') or v.get('owner')} | {'yes' if v.get('needs_verification') else '—'} |")
    L += ["","## 6. References","","| Key | Citation |","| --- | --- |"] + [f"| {k} | {REFS[k]} |" for k in sorted(REFS)]
    L += ["","## 7. Verification list","","Feeds the testing and prototyping rollout plan. Drivers first, then register entries (AQS-REG-002) flagged needs_verification.","",
          "| Item | Value | Verification test |","| --- | --- | --- |"]
    L += [f"| driver {k} | {json.dumps(v['value'])} {v['units']} | {v['verification_test']} |" for k,v in d.items() if v.get('needs_verification')]
    L += [f"| {m['id']} | {str(m['value'])[:60]} {m.get('units','')} | {m['verification_test']} |" for m in man if m.get('needs_verification')]
    open(os.path.join(ROOT,'docs-authority/PARAMETRIC_MODEL.md'),'w').write('\n'.join(L)+'\n')
    if errs: raise SystemExit('; '.join(errs))
    print(len(mis), sum(1 for v in d.values() if v.get('needs_verification')), sum(1 for m in man if m.get('needs_verification')))
if __name__=='__main__': main()
